// Notification and call sounds (wwwroot/sounds, generated by tools/sounds/sounds-gen.py; demo in
// docs/mockups/ipop-apple/sounds.html). Each module has its own default sound; the user can pick
// another one per module and set one volume in Settings → Notifications. Prefs live in localStorage.
// Decoded once through WebAudio so a sound plays instantly and the volume applies to every sound.
(function () {
    const KEY = 'notification-sounds';
    const MODULES = ['dm', 'group', 'mention', 'mail', 'meeting', 'project', 'announce', 'notes', 'tickets', 'system'];
    // Same melody, louder: meeting reminder, mandatory memo / condolence. Only used while the module
    // keeps its default sound — a sound the user picked plays as picked.
    const URGENT = { meeting: 'meeting-urgent', announce: 'announce-firm' };
    const CHOICES = [
        ['dm', 'Bubble'], ['group', 'Pebble'], ['mention', 'Spark'], ['mail', 'Envelope'], ['meeting', 'Doorbell'],
        ['meeting-urgent', 'Doorbell (loud)'], ['project', 'Tasker'], ['announce', 'Herald'], ['announce-firm', 'Herald (firm)'],
        ['notes', 'Paper'], ['tickets', 'Lifeline'], ['system', 'Ping'], ['x-glass', 'Crystal'], ['x-drop', 'Drop'], ['x-harp', 'Harp'],
    ];
    const FILES = new Set([...CHOICES.map(c => c[0]), 'tick', 'ringtone', 'ringback', 'hangup']);

    // loopGen identifies the current loop() call: a start that finishes loading after a newer
    // loop()/stopLoop() must not play, even for the same sound (two "Ringing" updates in a row).
    // Every looping source is tracked so a stop can never miss one.
    let ctx = null, master = null, loopGen = 0;
    const loops = new Set();
    const buffers = new Map();

    function prefs() {
        let p = {};
        // Per account (js/user-store.js); signed out = defaults.
        const store = window.ipopUserStore;
        try { p = JSON.parse((store ? store.getMine(KEY) : localStorage.getItem(KEY)) || '{}') || {}; } catch { }
        const vol = Number.isFinite(p.volume) ? Math.min(100, Math.max(0, p.volume)) : 80;
        return { volume: vol, map: Object.assign({}, p.map) };
    }

    function audio() {
        if (!ctx || ctx.state === 'closed') {
            const Ctx = window.AudioContext || window.webkitAudioContext;
            if (!Ctx) return null;
            ctx = new Ctx();
            master = ctx.createGain();
            master.connect(ctx.destination);
        }
        if (ctx.state === 'suspended') ctx.resume().catch(() => { });
        master.gain.value = prefs().volume / 100;
        return ctx;
    }

    function load(name) {
        if (!buffers.has(name)) {
            const p = fetch(`sounds/${name}.mp3`)
                .then(r => { if (!r.ok) throw new Error(r.status); return r.arrayBuffer(); })
                .then(b => audio().decodeAudioData(b));
            p.catch(() => buffers.delete(name)); // retry next time
            buffers.set(name, p);
        }
        return buffers.get(name);
    }

    async function play(name, { loop = false, volume, gen } = {}) {
        if (!name || !FILES.has(name)) return;
        const c = audio();
        if (!c) return;
        try {
            const buf = await load(name);
            if (loop && gen !== loopGen) return; // stopped (or replaced) while loading
            const src = c.createBufferSource();
            src.buffer = buf;
            src.loop = loop;
            let out = master;
            if (volume != null) {
                out = c.createGain();
                out.gain.value = volume / 100;
                out.connect(c.destination);
            }
            src.connect(out);
            if (loop) { stopSources(); loops.add(src); }
            src.start();
        } catch { /* blocked or missing — a sound is never essential */ }
    }

    function stopSources() {
        for (const src of loops) { try { src.stop(); } catch { } try { src.disconnect(); } catch { } }
        loops.clear();
    }

    function stopLoop() {
        loopGen++;
        stopSources();
    }

    // Browsers keep audio locked until the first click or key press on the page; unlock early so a
    // notification arriving later is heard, and warm the cache for the common sounds.
    const unlock = () => {
        const c = audio();
        if (c) ['dm', 'group', 'mail', 'ringtone', 'ringback', 'hangup'].forEach(n => load(n).catch(() => { }));
        removeEventListener('pointerdown', unlock, true);
        removeEventListener('keydown', unlock, true);
    };
    addEventListener('pointerdown', unlock, true);
    addEventListener('keydown', unlock, true);

    window.ipopSound = {
        modules: MODULES,
        choices: CHOICES,
        /// The sound for a module (dm, group, mention, mail, meeting, project, announce, notes, tickets, system).
        playFor(module, urgent) {
            // Hidden tab with push active: the service worker's Windows toast owns the alert sound.
            if (document.visibilityState === 'hidden' && window.ipopPushBackgroundHandoff) return;
            if (!MODULES.includes(module)) module = 'system';
            const picked = prefs().map[module];
            const name = picked === undefined ? module : picked; // "" = no sound
            play(urgent && name === module && URGENT[module] ? URGENT[module] : name);
        },
        play: name => play(name),
        /// Settings preview: plays at the volume on the slider, not the saved one.
        preview: (name, volume) => play(name, { volume }),
        /// Repeating call tone (ringtone / ringback); the files carry their own silence gap.
        loop(name) { stopLoop(); play(name, { loop: true, gen: loopGen }); },
        stopLoop,
        getPrefs() {
            const p = prefs();
            return { volume: p.volume, map: Object.fromEntries(MODULES.map(m => [m, p.map[m] === undefined ? m : p.map[m]])) };
        },
        setPrefs(volume, map) {
            const clean = {};
            for (const m of MODULES) if (map && map[m] !== undefined && map[m] !== m && (map[m] === '' || FILES.has(map[m]))) clean[m] = map[m];
            const json = JSON.stringify({ volume: Math.round(volume), map: clean });
            if (window.ipopUserStore) window.ipopUserStore.setMine(KEY, json); else localStorage.setItem(KEY, json);
            if (master) master.gain.value = volume / 100;
        },
    };
})();
